import{_ as t,c as n,b as o,o as r}from"./app-CKWO8MmE.js";const s={};function i(p,e){return r(),n("div",null,e[0]||(e[0]=[o('<p><a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multi-Vendor Marketplace for Shopify</a> is here with another marketplace shipping feature app, i.e., <strong>FedEx</strong>.</p><h2 id="fedex" tabindex="-1"><a class="header-anchor" href="#fedex"><span>FedEx</span></a></h2><p><a href="https://www.fedex.com/en-us/home.html" target="_blank" rel="noopener noreferrer">FedEx</a> Corporation is an American multinational courier delivery service.</p><p>Using this featured app, the merchants can enable shipment through <strong>FedEx</strong>. Moreover, he can allow <strong>US</strong> <strong>sellers</strong> to automatically generate shipping labels.</p><p><strong>FedEx</strong> feature app is available only with the Multivendor <strong>Pro</strong> <strong>Plan</strong> ($60/month). Moreover, you need to enable the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-shipping/" target="_blank" rel="noopener noreferrer"><strong>Shipping</strong></a> add-on (free) from the &#39;featured apps&#39; section of the app.</p><p><strong>CHARGES:</strong></p><p>This feature will have an additional charge of <strong>USD 10 per month</strong> over &amp; above your current multivendor marketplace plan.</p><p><strong>NOTE:</strong></p><p>Above all, access to Shipping requires your Shopify store to be on the plan that supports <strong>Real-Time Carrier-Calculated Shipping</strong>.</p><p>Currently, the FedEx Shipping feature app will only work for <strong>US Merchants</strong>.</p><p>FEDEX SHIPPING IS BOTH FOR <strong>RATE CALCULATION &amp; FULFILLMENT</strong></p><h2 id="installation" tabindex="-1"><a class="header-anchor" href="#installation"><span>Installation</span></a></h2><p>The admin needs to visit the <strong>multi-vendor marketplace admin panel</strong> &gt; click on the <strong>three dots</strong> &gt; click on the <strong>featured apps</strong>. Further, <strong>enable</strong> the <strong>FedEx</strong> feature app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/image-13-1200x597.png" alt="image-13"></p><p>Furthermore, <strong>agree</strong> &amp; <strong>approve</strong> the charges:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/demo-store-Approve-fees-Shopify-2.png" alt="123"></p><p>Shopify Backend (Admin End)</p><h2 id="configuration-admin-end" tabindex="-1"><a class="header-anchor" href="#configuration-admin-end"><span>Configuration: Admin End</span></a></h2><p>Firstly, the admin needs to enable this shipping method from the shipping configuration. So, for this, visit:</p><p><strong>Multivendor marketplace admin panel</strong> &gt; <strong>configuration</strong> &gt; <strong>shipping configuration</strong>.</p><p>Click on the <strong>three dots</strong> under the <strong>Action</strong> menu &amp; further, click on <strong>enable</strong>.</p><p><strong>Note</strong>: Kindly choose only those shipping services which you need. Don’t keep all the services selected otherwise it creates delay to retrieve shipping rates at the storefront.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Configuration-Admin-3.png" alt="123"></p><p>MultiVendor Marketplace Admin End</p><p>Moving on, the admin needs to configure the FedEx Shipping. So, for this, either click on <strong>Configure Shipping</strong> or go to <strong>multi vendor marketplace admin panel</strong> &gt; <strong>configuration</strong> &gt; <strong>FedEx Shipping Configuration</strong>. Refer:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Configuration-Admin-1-1.png" alt="123"></p><p>MultiVendor Marketplace Admin End</p><h2 id="configure-fedex-express" tabindex="-1"><a class="header-anchor" href="#configure-fedex-express"><span>Configure FedEx Express</span></a></h2><p><strong>SANDBOX MODE</strong></p><p>If you want to test the functionality of this shipping add-on, enable the sandbox mode. In short, use the sandbox mode for testing purposes only.</p><p>Enter the following details: <strong>FEDEX ACCOUNT NUMBER</strong>, <strong>FEDEX ACCESS KEY</strong>, <strong>FEDEX PASSWORD</strong> &amp; <strong>FEDEX METER NUMBER</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Fedex-Configuration-Admin-1.png" alt="123"></p><p>MultiVendor Marketplace Admin End</p><p>Further, choose the shipping service name for order fulfillment and Choose who will bear the shipping label charges, thus, the admin or the seller. (This is an extra cost apart from what the customer has paid.)</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Fedex-Configuration-Admin-2.png" alt="123"></p><p>MultiVendor Marketplace Admin End</p><h2 id="set-shipping-method-for-sellers" tabindex="-1"><a class="header-anchor" href="#set-shipping-method-for-sellers"><span>Set Shipping Method For Sellers:</span></a></h2><p>The admin can further set the shipping methods for his sellers.<br> Go to <strong>multi vendor marketplace admin panel</strong> &gt; <strong>Sellers</strong> &gt; <strong>Seller Listing</strong> &gt; <strong>Edit</strong> (under <strong>Action</strong>). <br> On the edit seller page, the admin will have the following block from where he can enable/disable/set as default:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Edit-Seller-Admin-2.png" alt="123"></p><p>MultiVendor Marketplace Admin End</p><p>Further, the admin can view all the sellers which are using this shipping method by going to <strong>multi vendor marketplace admin panel</strong> &gt; <strong>configuration</strong> &gt; <strong>Shipping</strong> <strong>Configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Configuration-Admin-2-1.png" alt="123"></p><p>MultiVendor Marketplace Admin End</p><h2 id="make-shipping-address-phone-number-mandatory" tabindex="-1"><a class="header-anchor" href="#make-shipping-address-phone-number-mandatory"><span>Make <strong>Shipping</strong> <strong>Address Phone Number</strong> Mandatory</span></a></h2><p>To use this feature add-on, the admin needs to make the <strong>Shipping</strong> <strong>address phone number mandatory</strong> at the time of <strong>checkout</strong>.</p><p>So, to do this, go to <strong>Shopify Backend</strong> &gt; <strong>Settings</strong> &gt; <strong>Checkout</strong> &gt; Under <strong>Form Options</strong>, make <strong>Shipping</strong> <strong>address phone number</strong> as <strong>Required</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/demo-store-Checkout-Shopify-1200x597.png" alt="133"></p><p>Shopify Backend (Admin End)</p><h3 id="configuration-seller-end" tabindex="-1"><a class="header-anchor" href="#configuration-seller-end"><span>Configuration: Seller End</span></a></h3><p>Further, the seller can configuration FedEx Shipping from his panel.</p><p>Go to <strong>multi vendor marketplace seller panel</strong> &gt; <strong>configuration</strong> &gt; <strong>shipping configuration</strong>&gt; <strong>enable</strong> the shipping:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-Configuration-Seller-•-Multivendor-MarketPlace-5.png" alt="123"></p><p>MultiVendor Marketplace Seller End</p><p>Further, go to <strong>Global Configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-Configuration-Seller-•-Multivendor-MarketPlace-1-2.png" alt="123"></p><p>MultiVendor Marketplace Seller End</p><p>So, from here, the seller can do the <strong>SHIPPING PACKET CONFIGURATION</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-Configuration-Seller-•-Multivendor-MarketPlace-6.png" alt="123"></p><p>MultiVendor Marketplace Seller End</p><p><strong>Note: LBH</strong> &gt; 1 inch (2.54 cm)</p><p>Moreover, the <strong>FEDEX SHIPPING CONFIGURATION</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-Configuration-Seller-•-Multivendor-MarketPlace-1-3.png" alt="123"></p><p>MultiVendor Marketplace Seller End</p><p>The seller can set the shipping method as <strong>by-default</strong> so that every single product created by him will have <strong>FedEx Shipping</strong> as the <strong>by-default shipping method</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-Configuration-Seller-•-Multivendor-MarketPlace-2-2.png" alt="123"></p><p>MultiVendor Marketplace Seller End</p><p>If not this, the seller can set the shipping method on individual products while adding/editing them.</p><p>So, go to <strong>Multi-vendor marketplace seller panel</strong> &gt; <strong>Products</strong> &gt;<strong>Product Listing</strong> &gt; <strong>Add</strong>/<strong>Edit</strong> the Product:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Screenshot-from-2019-09-17-12-42-45.png" alt="123"></p><p>MultiVendor Marketplace Seller End</p><h2 id="shopify-store-frontend" tabindex="-1"><a class="header-anchor" href="#shopify-store-frontend"><span>Shopify Store Frontend</span></a></h2><p>Likewise, the customer will have an option to select the shipping method as <strong>FedEx</strong> after entering the information:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-demo-store-Checkout-1.png" alt="123"></p><h2 id="shipping-label-generation" tabindex="-1"><a class="header-anchor" href="#shipping-label-generation"><span>Shipping Label Generation</span></a></h2><p>Seller will have an option to generate a shipping label from their seller panel. Also, shipping labels can only be generated for <strong>fulfilled orders</strong>.</p><p><strong>Fulfilling order by FedEx</strong>:</p><p>Go to <strong>Multi-vendor marketplace seller panel</strong> &gt; <strong>Orders</strong> &gt; <strong>Order Listing</strong> &gt; <strong>View</strong> (under <strong>Action</strong>). Select the method of order fulfillment as <strong>FedEx</strong> and fulfill the order. As soon as the order will be fulfilled, the shipping label will be automatically downloaded.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Order-Details-Seller-•-Multivendor-MarketPlace-1-2.png" alt="123"></p><p>Click on fulfill</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Order-Details-Seller-•-Multivendor-MarketPlace-2.png" alt="123"></p><p>Agree &amp; Fulfill: This block will have the information regarding who is bearing the shipping label charges.</p><p>Moreover, if you again want to download the shipping label, go to ADDITIONAL ORDER DETAILS, click on <strong>Actions</strong> &gt; <strong>Print Shipping Label</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Order-Details-Seller-•-Multivendor-MarketPlace-3.png" alt="212"></p><p>Furthermore, this is how the shipping label will be downloaded in pdf form:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Screenshot-from-2019-09-17-14-31-53-1.png" alt="123"></p><h2 id="create-a-pickup-request" tabindex="-1"><a class="header-anchor" href="#create-a-pickup-request"><span>Create a Pickup Request</span></a></h2><p>The seller can generate a pickup request for the FedEx courier services to pick the order from your warehouse:</p><p>For this, go to ADDITIONAL ORDER DETAILS, click on <strong>Actions</strong> &gt; <strong>Create Pickup Request</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Order-Details-Seller-•-Multivendor-MarketPlace-4.png" alt="123"></p><p>This action will give you a pop-up:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Order-Details-Seller-•-Multivendor-MarketPlace-5.png" alt="123"></p><p>Enter the required details &amp; save.</p><p>Further, the seller can view the generated pickup request on the same page under PICKUP REQUEST DETAILS section:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Order-Details-Seller-•-Multivendor-MarketPlace-6.png" alt="123"></p><p>The seller can view the pickup request details &amp; also, can cancel the request.</p><p><strong>NOTE:</strong></p><p>The seller can delete the pickup request only before the <strong>FedEx Ready time</strong> set by him while creating the request. Once created, the pickup request can&#39;t be generated or edited again.</p>',97)]))}const a=t(s,[["render",i]]),g=JSON.parse('{"path":"/classic/Featured-App/Shipping/FEDEX%20SHIPPING.html","title":"FEDEX SHIPPING","lang":"en-US","frontmatter":{"title":"FEDEX SHIPPING","description":"FEDEX SHIPPING","date":"2025-07-18T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":2,"title":"FedEx","slug":"fedex","link":"#fedex","children":[]},{"level":2,"title":"Installation","slug":"installation","link":"#installation","children":[]},{"level":2,"title":"Configuration: Admin End","slug":"configuration-admin-end","link":"#configuration-admin-end","children":[]},{"level":2,"title":"Configure FedEx Express","slug":"configure-fedex-express","link":"#configure-fedex-express","children":[]},{"level":2,"title":"Set Shipping Method For Sellers:","slug":"set-shipping-method-for-sellers","link":"#set-shipping-method-for-sellers","children":[]},{"level":2,"title":"Make Shipping Address Phone Number Mandatory","slug":"make-shipping-address-phone-number-mandatory","link":"#make-shipping-address-phone-number-mandatory","children":[{"level":3,"title":"Configuration: Seller End","slug":"configuration-seller-end","link":"#configuration-seller-end","children":[]}]},{"level":2,"title":"Shopify Store Frontend","slug":"shopify-store-frontend","link":"#shopify-store-frontend","children":[]},{"level":2,"title":"Shipping Label Generation","slug":"shipping-label-generation","link":"#shipping-label-generation","children":[]},{"level":2,"title":"Create a Pickup Request","slug":"create-a-pickup-request","link":"#create-a-pickup-request","children":[]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"classic/Featured-App/Shipping/FEDEX SHIPPING.md"}');export{a as comp,g as data};
